  [UnitySetUp]public IEnumerator Setup(){f=new BeforeDemolitionChapterFixture("tutorial.visual",Array.Empty<StoryMilestoneDefinition>());var input=f.root.AddComponent<InputReader>();input.asset=AssetDatabase.LoadAssetAtPath<InputActionAsset>("Assets/HorrorGameplay/Input/HorrorInput.inputactions");f.game.input=input;s=f.root.AddComponent<TutorialCardSystem>();s.game=f.game;s.catalog=AssetDatabase.LoadAssetAtPath<TutorialCardCatalog>("Assets/HorrorGameplay/Data/TutorialCards/TutorialCardCatalog.asset");TutorialPreferences.Set(TutorialMode.Full);yield return f.Activate();s.SetMode(TutorialMode.Full);}
