  [UnityTest]public IEnumerator CardsRenderAtFourAspectRatiosWithTextAndButtonsInsideScreen(){s.Discover("lockpick");foreach(var p in s.State.pending)p.remaining=0;s.Tick(.1f);Assert.That(s.IsOpen,Is.True);yield return new WaitForSecondsRealtime(.25f);var copy=new GameObject("Tutorial UI proof",typeof(RectTransform));var view=copy.AddComponent<TutorialCardView>();view.Build(s,s.catalog.font);view.Show(s.Current,false);var canvas=copy.GetComponent<Canvas>();var cameraGo=new GameObject("Tutorial UI proof camera");var camera=cameraGo.AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.transform.position=new Vector3(0,0,-10);camera.cullingMask=1<<5;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.035f,.03f);canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;foreach(var t in copy.GetComponentsInChildren<Transform>(true))t.gameObject.layer=5;
   try{foreach(var size in new[]{new Vector2Int(1920,1080),new Vector2Int(1440,900),new Vector2Int(1024,768),new Vector2Int(2560,1080)}){var rt=new RenderTexture(size.x,size.y,24);var old=RenderTexture.active;Texture2D pixels=null;try{rt.Create();camera.targetTexture=rt;Canvas.ForceUpdateCanvases();yield return null;yield return null;view.fade.alpha=1;Canvas.ForceUpdateCanvases();var screen=(RectTransform)copy.transform;Assert.That(view.panel.rect.width*view.panel.localScale.x,Is.LessThanOrEqualTo(screen.rect.width));Assert.That(view.panel.rect.height*view.panel.localScale.y,Is.LessThanOrEqualTo(screen.rect.height));foreach(var text in copy.GetComponentsInChildren<TMPro.TMP_Text>().Where(t=>t.gameObject.activeInHierarchy)){text.ForceMeshUpdate();Assert.That(text.isTextOverflowing,Is.False,text.name+" / "+size+" / "+text.text);}UnityEngine.Rendering.RenderPipeline.SubmitRenderRequest(camera,new UnityEngine.Rendering.RenderPipeline.StandardRequest{destination=rt,isPreview=false});RenderTexture.active=rt;pixels=new Texture2D(size.x,size.y,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,size.x,size.y),0,0);pixels.Apply();Assert.That(pixels.GetPixels32().Count(p=>p.r>100&&p.g>100&&p.b>100),Is.GreaterThan(2000));Directory.CreateDirectory("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101");File.WriteAllBytes("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101/card-"+size.x+"x"+size.y+".png",pixels.EncodeToPNG());}finally{camera.targetTexture=null;RenderTexture.active=old;rt.Release();UnityEngine.Object.Destroy(rt);if(pixels)UnityEngine.Object.Destroy(pixels);}}}finally{UnityEngine.Object.Destroy(copy);UnityEngine.Object.Destroy(cameraGo);}}
