 public sealed partial class BeforeDemolitionSchoolSceneTests {
  [UnityTest,Category("TutorialCards"),Timeout(120000)]public IEnumerator TutorialNativeWhistleAppearsOnLibraryEntryBeforeReadingLore(){var s=game.tutorials;var whistle=WhistleSystem.For(game);s.SetMode(TutorialMode.Full);yield return SecretaryAndKey();Assert.That(s.State.discovered,Does.Not.Contain("whistle"));game.player.Warp(new Vector3(41.7f,.05f,55.8f),180);yield return Until(()=>game.narrative.HasSignal("bd.school.library"),"Library entry");yield return Until(()=>s.IsOpen,"Whistle explanation on library entry",15);Assert.That(s.Current.id,Is.EqualTo("whistle"));Assert.That(whistle.State.loreKnown,Is.False,"No mural reading is required for this card");Assert.That(whistle.State.schoolHesitated,Is.False);s.Close();yield return Until(()=>game.CanControl,"Close whistle card");Assert.That(s.State.seen.Count(id=>id=="whistle"),Is.EqualTo(1));}

  [UnityTest,Category("TutorialCards"),Timeout(120000)]public IEnumerator TutorialNativeSecretaryPickupWaitsForSpeechAndPreservesCheckpoint(){var s=game.tutorials;Assert.That(s&&s.catalog,Is.True);s.SetMode(TutorialMode.Full);yield return GetPins();Assert.That(s.State.discovered,Does.Contain("lockpick"));Assert.That(s.State.seen,Does.Not.Contain("lockpick"));Assert.That(s.SafeToShow,Is.False,"Pickup dialogue must finish before tutorial");yield return Until(()=>s.IsOpen,"Tutorial after pickup speech",10);Assert.That(s.Current.id,Is.EqualTo("lockpick"));float battery=game.save.flashlight.BatterySeconds,tension=game.atmosphere.Tension;var phone=PhoneMessages.For(game);var def=phone.catalog.messages.First(d=>!phone.State.Has(d.id)&&!d.replyOnly);var pending=new PendingPhoneMessage{id=def.id,seconds=2};phone.State.pending.Add(pending);yield return new WaitForSecondsRealtime(.3f);Assert.That(pending.seconds,Is.EqualTo(2));Assert.That(phone.CanShowBanner||phone.BannerVisible,Is.False);Assert.That(game.save.flashlight.BatterySeconds,Is.EqualTo(battery));Assert.That(game.atmosphere.Tension,Is.EqualTo(tension));Assert.That(game.lockpick.Open(Training()),Is.False);phone.State.pending.Remove(pending);s.Close();yield return Until(()=>game.CanControl,"Tutorial releases controls");Assert.That(game.save.Save(),Is.True);Assert.That(game.save.TryReadCurrent(out var data),Is.True);Assert.That(data.tutorials.seen,Does.Contain("lockpick"));Assert.That(game.save.RestoreSnapshot(data),Is.True);game.narrative.InitializeAfterSession(true);Assert.That(s.State.seen,Does.Contain("lockpick"));Assert.That(s.Open("lockpick",false),Is.False,"Seen card cannot open automatically again");}
